#' Own Python Summary Example
#'
#' 
#' @param data .
#' @param measurement .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$route} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$backendTiming} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
pyservicedirect <- function(
    data,
    measurement = NULL,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyservicedirect requires jmvcore to be installed (restart may be required)")

    if ( ! missing(measurement)) measurement <- jmvcore::resolveQuo(jmvcore::enquo(measurement))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(measurement), measurement, NULL))


    options <- pyservicedirectOptions$new(
        measurement = measurement,
        showConsole = showConsole)

    analysis <- pyservicedirectClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

